import heapq

def match(orders):
    trades = []
    buy_book = []  # heap of (-price, seq, oid)
    sell_book = []  # heap of (price, seq, oid)
    orders_data = {}  # id -> [side, price, qty, seq, active]
    seq_counter = 0

    def add_to_book(oid):
        side, price, qty, seq, active = orders_data[oid]
        if side == 'buy':
            heapq.heappush(buy_book, (-price, seq, oid))
        else:
            heapq.heappush(sell_book, (price, seq, oid))

    def top_valid(book):
        while book:
            item = book[0]
            oid = item[2]
            if oid not in orders_data:
                heapq.heappop(book)
                continue
            side, price, qty, seq, active = orders_data[oid]
            if not active or qty <= 0:
                heapq.heappop(book)
                continue
            return oid
        return None

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            if oid in orders_data:
                if orders_data[oid][4] and orders_data[oid][2] > 0:
                    orders_data[oid][4] = False
            continue

        oid = order[1]
        side = order[2]
        if typ == 'market':
            price = None
            qty = order[3]
        else:
            price = order[3]
            qty = order[4]

        remaining = qty
        seq = seq_counter
        seq_counter += 1

        if side == 'buy':
            opp_book = sell_book
        else:
            opp_book = buy_book

        while remaining > 0:
            opp_id = top_valid(opp_book)
            if opp_id is None:
                break
            opp_side, opp_price, opp_qty, opp_seq, opp_active = orders_data[opp_id]

            if typ != 'market':
                if side == 'buy' and opp_price > price:
                    break
                if side == 'sell' and opp_price < price:
                    break

            trade_qty = min(remaining, opp_qty)
            if side == 'buy':
                trades.append([oid, opp_id, opp_price, trade_qty])
            else:
                trades.append([opp_id, oid, opp_price, trade_qty])

            remaining -= trade_qty
            orders_data[opp_id][2] -= trade_qty
            if orders_data[opp_id][2] == 0:
                orders_data[opp_id][4] = False
                # will be popped lazily next time top_valid is called

        if typ == 'limit':
            if remaining > 0:
                orders_data[oid] = [side, price, remaining, seq, True]
                add_to_book(oid)
            else:
                orders_data[oid] = [side, price, 0, seq, False]
        # ioc and market: discard remainder, no need to store

    return trades

